@Test
void missingSessionUsesPublicStructuredError() {
    try (var runtime = runtime(new ScriptedModelProvider())) {
        JiException missing = assertThrows(JiException.class, () -> runtime.loadSession("missing"));
        assertEquals(ErrorCode.SESSION_NOT_FOUND, missing.error().code());
        assertEquals(Map.of("sessionId", "missing"), missing.error().parameters());
    }
}

@Test
void closedSessionUsesPublicStructuredError() {
    try (var runtime = runtime(new ScriptedModelProvider())) {
        AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
        session.close();
        JiException closed = assertThrows(JiException.class, () -> session.prompt("hello"));
        assertEquals(ErrorCode.SESSION_NOT_FOUND, closed.error().code());
        assertEquals(session.id(), closed.error().parameters().get("sessionId"));
    }
}

